start='''#[tauri::command]\npub fn open_production_batch_in_endlume(endlume_path:String,manifest_path:String)->Result<HandoffReceipt,String>{\n    let(m,_)=load_manifest(&manifest_path)?;let app=PathBuf::from(&endlume_path);if !app.exists(){return Err("ENDLUME Studio не найден".into());}\n    #[cfg(target_os="macos")]\n    {\n        let home=std::env::var("HOME").map_err(|_|"HOME не найден".to_string())?;let inbox=PathBuf::from(home).join("Library/Application Support/studio.endlume.desktop/VYRON Inbox");fs::create_dir_all(&inbox).map_err(|e|e.to_string())?;\n        let request=inbox.join(format!("{}.json",safe_component(&m.batch_id)));atomic_json(&request,&json!({"schemaVersion":1,"batchId":m.batch_id,"manifestPath":manifest_path,"requestedAt":Utc::now().to_rfc3339()}))?;\n        if !request.is_file(){return Err("Не удалось создать inbox-запрос ENDLUME".into())}Command::new("open").arg(&app).spawn().map_err(|e|format!("Не удалось открыть ENDLUME: {e}"))?;\n        return Ok(HandoffReceipt{batch_id:m.batch_id,manifest_path,request_path:request.to_string_lossy().into_owned()});\n    }\n    #[cfg(not(target_os="macos"))]\n    {Command::new(&app).spawn().map_err(|e|e.to_string())?;Ok(HandoffReceipt{batch_id:m.batch_id,manifest_path,request_path:String::new()})}\n}'''
new='''#[tauri::command]\npub fn open_production_batch_in_endlume(endlume_path:String,manifest_path:String,selected_project_ids:Option<Vec<String>>,force_resend:Option<bool>)->Result<HandoffReceipt,String>{\n    let(m,_)=load_manifest(&manifest_path)?;let app=PathBuf::from(&endlume_path);if !app.exists(){return Err("ENDLUME Studio не найден".into());}\n    let requested=selected_project_ids.unwrap_or_else(||m.projects.iter().map(|p|p.project_id.clone()).collect());\n    let mut seen=HashSet::new();let ids=requested.into_iter().filter(|x|seen.insert(x.clone())).collect::<Vec<_>>();if ids.is_empty(){return Err("Не выбраны проекты для ENDLUME".into())}\n    let idset=ids.iter().cloned().collect::<HashSet<_>>();let selected=m.projects.iter().filter(|p|idset.contains(&p.project_id)).cloned().collect::<Vec<_>>();\n    if selected.len()!=ids.len(){return Err("Один или несколько выбранных проектов отсутствуют в batch".into())}\n    let mut ledger=read_handoff_ledger(&m);let repeated=ids.iter().filter(|id|ledger.projects.contains_key(*id)).cloned().collect::<Vec<_>>();\n    if !repeated.is_empty()&&!force_resend.unwrap_or(false){return Err(format!("ENDLUME_ALREADY_SENT:{}",repeated.join(",")))}\n    let handoff_id=Uuid::new_v4().to_string();let root=PathBuf::from(&m.root_path);\n    // ENDLUME validates that manifest parent == rootPath, therefore the immutable subset manifest\n    // is placed beside batch.json. Original batch.json and the other projects are never mutated.\n    let mut subset=m.clone();subset.projects=selected;subset.project_count=subset.projects.len();subset.status="Передано ENDLUME".into();\n    let subset_path=root.join(format!(".vyron-handoff-{}.json",safe_component(&handoff_id)));atomic_json(&subset_path,&subset)?;\n    let now=Utc::now().to_rfc3339();for id in &ids{let row=ledger.projects.entry(id.clone()).or_default();row.sent_at=now.clone();row.count=row.count.saturating_add(1);}ledger.schema_version=1;atomic_json(&handoff_ledger_path(&m),&ledger)?;\n    #[cfg(target_os="macos")]\n    {\n        let home=std::env::var("HOME").map_err(|_|"HOME не найден".to_string())?;let inbox=PathBuf::from(home).join("Library/Application Support/studio.endlume.desktop/VYRON Inbox");fs::create_dir_all(&inbox).map_err(|e|e.to_string())?;\n        let request=inbox.join(format!("{}-{}.json",safe_component(&m.batch_id),safe_component(&handoff_id)));atomic_json(&request,&json!({"schemaVersion":1,"batchId":m.batch_id,"manifestPath":subset_path.to_string_lossy(),"requestedAt":now,"selectedProjectIds":ids,"sourceManifestPath":manifest_path,"handoffId":handoff_id}))?;\n        if !request.is_file(){return Err("Не удалось создать inbox-запрос ENDLUME".into())}Command::new("open").arg(&app).spawn().map_err(|e|format!("Не удалось открыть ENDLUME: {e}"))?;\n        return Ok(HandoffReceipt{batch_id:m.batch_id,manifest_path:subset_path.to_string_lossy().into_owned(),request_path:request.to_string_lossy().into_owned(),selected_project_ids:ids,repeated_project_ids:repeated});\n    }\n    #[cfg(not(target_os="macos"))]\n    {Command::new(&app).spawn().map_err(|e|e.to_string())?;Ok(HandoffReceipt{batch_id:m.batch_id,manifest_path:subset_path.to_string_lossy().into_owned(),request_path:String::new(),selected_project_ids:ids,repeated_project_ids:repeated})}\n}'''
rep(p,start,new)
